#!/usr/bin/env bash
set -Eeuo pipefail
# Forward-register registerCentralOffsitePlugin on the current live baseline.
TARGET='/home/agent/ssh-mcp-server/src/plugins/hostActions.js'
EXPECTED_OLD='22ecf31569cb7ef9e1b13263f5ee799b380e3b1f410324d430a2520f14765d3b'
EXPECTED_NEW='70f163f24d6431d6e5a11672c0ee4115cd31e5fdee767766fbca28000720cfbc'
SERVICE='prhm-agent-mcp.service'
BACKUP_DIR='/var/backups/prhm-agent-mcp-central-offsite-registration-v2'
mkdir -p "$BACKUP_DIR"
CURRENT="$(sha256sum "$TARGET" | awk '{print $1}')"
if [[ "$CURRENT" == "$EXPECTED_NEW" ]]; then
  /usr/local/bin/prhm-node --check "$TARGET"
  systemctl is-active --quiet "$SERVICE"
  echo 'AGENT_MCP_CENTRAL_OFFSITE_REGISTRATION_V2=ALREADY_APPLIED'
  exit 0
fi
[[ "$CURRENT" == "$EXPECTED_OLD" ]] || { echo "PREIMAGE_SHA_MISMATCH:$CURRENT" >&2; exit 41; }
TMP="$(mktemp /tmp/prhm-agent-mcp-central-offsite-v2.XXXXXX.js)"
BACKUP="$BACKUP_DIR/hostActions.js.$(date -u +%Y%m%dT%H%M%SZ).$EXPECTED_OLD.bak"
rollback(){ rc=$?; set +e; [[ -f "$BACKUP" ]] && install -m 0644 "$BACKUP" "$TARGET" && systemctl restart "$SERVICE"; rm -f "$TMP"; echo 'ROLLBACK_PERFORMED=1' >&2; exit "$rc"; }
trap rollback ERR
printf '%s' '' | base64 -d > "$TMP"
[[ "$(sha256sum "$TMP" | awk '{print $1}')" == "$EXPECTED_NEW" ]]
/usr/local/bin/prhm-node --check "$TMP"
cp -a "$TARGET" "$BACKUP"
install -m 0644 "$TMP" "$TARGET"
[[ "$(sha256sum "$TARGET" | awk '{print $1}')" == "$EXPECTED_NEW" ]]
/usr/local/bin/prhm-node --check "$TARGET"
systemctl restart "$SERVICE"
systemctl is-active --quiet "$SERVICE"
rm -f "$TMP"
trap - ERR
echo 'AGENT_MCP_CENTRAL_OFFSITE_REGISTRATION_V2=APPLIED'
echo "LIVE_SHA256=$EXPECTED_NEW"
echo "BACKUP=$BACKUP"
